        internal
        onlyActiveMarket(args.asset)
        returns (PlaceOrderResult memory result)
    {
        // sanity check: non liquidation taker order can't be placed on the backstop book
        if (bookType == BookType.BACKSTOP && args.tif != TiF.MOC) revert InvalidBackstopOrder();

        // Adding a one-tick buffer for post-only backstop orders
        if (bookType == BookType.BACKSTOP && args.price <= getCurrentMarketPrice(self, args.asset) + tickSize) revert InvalidBackstopOrder();

        if (args.reduceOnly) {
            _validateReduceOnlyOrder({
                self: self,
                account: account,
                subaccount: args.subaccount,
                orderAmount: args.amount,
                side: args.side,
                baseDenominated: args.baseDenominated
            });
        }

        return CLOBLib.placeOrder(account, args, bookType);
    }

function linkReduceOnlyOrder(
        Market storage self,
        address account,
        uint256 subaccount,
        uint256 orderId,
        BookType bookType
    ) internal {
        if (bookType == BookType.STANDARD) _linkReduceOnlyStandard(self, account, subaccount, orderId);
        else if (bookType == BookType.BACKSTOP) {
            // Ensure that linking backstop orders is done safely
            require(isValidBackstopOrder(self, orderId), "Invalid backstop order");
            _linkReduceOnlyBackstop(self, account, subaccount, orderId);
